import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Grade } from '../people/people';
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';

/**
 * A grade's rate: a percent with two decimals, from a date (yyyy-MM-dd; '' when it applies from the
 * beginning of time).
 */
export type Rate = { grade: Grade; pct: string; from: string };

export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

/** The sheet's rates, by grade then from-date (none first). */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: async () =>
      (await getJson<{ rates: Rate[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`)).rates,
  });
}

/**
 * A grade's rate in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or
 * before it. Null when the date is before every rate the grade has (or it has none).
 */
export function rateOn(rates: Rate[], grade: Grade, date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.grade !== grade || r.from > date) continue;
    if (best === null || r.from > best.from) best = r;
  }
  return best?.pct ?? null;
}

/** The sheet's rate for a grade on a date, or null when none is in force (or the rates are not read yet). */
export function useGradeRate(sheetId: string, grade: Grade, date: string): string | null {
  return rateOn(useRates(sheetId).data ?? [], grade, date);
}

/** A percent as a rate takes it: 0.00 or more, with up to two decimals. */
export const PCT = /^\d+(\.\d{1,2})?$/;

export const NA = 'n/a';

/** A two-decimal number as a whole count of hundredths. */
function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.trim().split('.');
  return BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
}

function showCents(cents: bigint): string {
  return `${cents / 100n}.${(cents % 100n).toString().padStart(2, '0')}`;
}

/**
 * An amount times a rate, divided by 100, rounded half to even to two decimals; n/a with no rate.
 * Worked in whole numbers so no floating-point error creeps in (amounts and rates are never
 * negative).
 */
export function due(amount: string, pct: string | null): string {
  if (pct === null) return NA;
  // cents × basis points is the due in millionths of a unit: 10000 of them to the cent.
  const x = hundredths(amount) * hundredths(pct);
  const cents = x / 10000n;
  const rest = x % 10000n;
  return showCents(rest > 5000n || (rest === 5000n && cents % 2n === 1n) ? cents + 1n : cents);
}

/** Due values added up, skipping n/a. */
export function sumDue(values: string[]): string {
  return showCents(values.filter((v) => v !== NA).reduce((n, v) => n + hundredths(v), 0n));
}

/**
 * A claim's due: the one fixed when it was settled, else the figure its person's last statement
 * bound it to, else its amount at the rate in force on its date.
 */
export function claimDue(claim: Claim, pct: string | null): string {
  if (claim.due !== '') return claim.due;
  return claim.stated ? claim.statedDue : due(claim.amount, pct);
}

/**
 * A person's due-total: the figures of their claims that count (none OPEN while they are `held`) (each at the rate in force on its
 * date), added up, skipping n/a. With no rate for their grade today it is n/a, unless a settled
 * claim that counts keeps a fixed figure (settled, or bound by a statement).
 */
export function personDueTotal(rates: Rate[], grade: Grade, today: string, claims: Claim[], held: boolean): string {
  const counted = claims.filter((c) => counts(c, held));
  if (rateOn(rates, grade, today) === null && !counted.some((c) => c.due !== '' || c.stated)) return NA;
  return sumDue(counted.map((c) => claimDue(c, rateOn(rates, grade, c.date))));
}

import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import { useClaims } from '../claims/claims';
import { GRADES, usePeople } from '../people/people';
import type { Grade, Person } from '../people/people';
import { useUser } from '../session/session';
import { useSheetToday } from '../sheet/sheet';
import { NA, PCT, personDueTotal, rateOn, ratesKey, sumDue, useRates } from './rates';
import type { Rate } from './rates';

type Fields = { grade: Grade; pct: string; from: string };
const EMPTY: Fields = { grade: 'A', pct: '', from: '' };

// The sheet's rates: a form that sets a grade's rate from a date (or from the beginning of time),
// every rate set, and each grade's rate in force on the sheet's today.
function Rates({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const [fields, setFields] = useState<Fields>(EMPTY);
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const save = useMutation({
    mutationFn: (body: Fields) =>
      postJson<Rate>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`, body, user),
    onSuccess: () => {
      setFields((f) => ({ ...f, pct: '', from: '' }));
      void queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
    },
    onError: () => setError('That rate could not be set.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const pct = fields.pct.trim();
    if (pct === '') {
      setError('A rate is required.');
      return;
    }
    if (!PCT.test(pct)) {
      setError('A rate is a percent of 0.00 or more, with up to two decimals.');
      return;
    }
    once((done) =>
      save.mutate({ grade: fields.grade, pct, from: fields.from.trim() }, { onSettled: done }),
    );
  };

  const change = (next: Partial<Fields>) => {
    setFields((f) => ({ ...f, ...next }));
    setError('');
  };

  const all = rates.data ?? [];

  return (
    <section data-testid="rates">
      <h2>Rates</h2>
      <form onSubmit={submit} data-testid="rate-form">
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={fields.grade}
            onChange={(e) => change({ grade: e.target.value as Grade })}
          >
            {GRADES.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input
            data-testid="rate-form-pct"
            inputMode="decimal"
            value={fields.pct}
            onChange={(e) => change({ pct: e.target.value })}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="date"
            data-testid="rate-form-from"
            value={fields.from}
            onChange={(e) => change({ from: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {error && (
          <p role="alert" data-testid="rate-form-error">
            {error}
          </p>
        )}
      </form>
      {rates.isError && (
        <p role="alert" data-testid="rates-error">
          The rates could not be read.
        </p>
      )}
      <table data-testid="rate-today">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate % today</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`rate-current-${g}`}>{rateOn(all, g, today) ?? NA}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="rate-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>From</th>
            <th>Rate %</th>
          </tr>
        </thead>
        <tbody>
          {all.map((r) => (
            <tr key={`${r.grade}-${r.from}`} data-testid={`rate-row-${r.grade}-${r.from || 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from || 'start'}</td>
              <td data-testid="rate-pct">{r.pct}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

function DueHead() {
  return <th>Due</th>;
}

// A person's due-total: the due figures of their claims that count, added up.
function PersonDueTotal({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = (useClaims(sheetId).data ?? []).filter((c) => c.personId === person.id);
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  return <td data-testid="person-due-total">{personDueTotal(rates, person.grade, today, claims, person.held)}</td>;
}

// The sheet's due-total: everyone's due-total added up, skipping those with no rate.
function DueTotal({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const totals = people.map((p) =>
    personDueTotal(rates, p.grade, today, claims.filter((c) => c.personId === p.id), p.held),
  );
  return (
    <p>
      Due in all: <strong data-testid="rollup-due-total">{sumDue(totals)}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: -10, Component: Rates }),
  SheetBody.fill({ order: 20, Component: DueTotal }),
  PersonHead.fill({ order: 20, Component: DueHead }),
  PersonRow.fill({ order: 20, Component: PersonDueTotal }),
];
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's body on the home screen. Everything kept per sheet (its people, claims,
 * settings) contributes here; it renders only once a user is signed in and a sheet is loaded, and
 * is remounted whenever a sheet is (re-)loaded, so a contribution starts from a fresh read.
 * Server data for a sheet lives under the query key ['sheet', sheetId, ...].
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
// A non-2xx response, carrying its status so a caller can tell one refusal from another.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

// A change is made by the signed-in user: name them, and the server records who made it.
function jsonHeaders(user?: string): HeadersInit {
  return user === undefined
    ? { 'Content-Type': 'application/json' }
    : { 'Content-Type': 'application/json', 'X-User': encodeURIComponent(user) };
}

export function postJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown, user?: string): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: jsonHeaders(user),
    body: JSON.stringify(body),
  });
}
